60: static void handleAbsEvent(_GLFWjoystick* js, int code, int value)
61: {
62:     const int index = js->linjs.absMap[code];
63: 
64:     if (code >= ABS_HAT0X && code <= ABS_HAT3Y)
65:     {
66:         static const char stateMap[3][3] =
67:         {
68:             { GLFW_HAT_CENTERED, GLFW_HAT_UP,       GLFW_HAT_DOWN },
69:             { GLFW_HAT_LEFT,     GLFW_HAT_LEFT_UP,  GLFW_HAT_LEFT_DOWN },
70:             { GLFW_HAT_RIGHT,    GLFW_HAT_RIGHT_UP, GLFW_HAT_RIGHT_DOWN },
71:         };
72: 
73:         const int hat = (code - ABS_HAT0X) / 2;
74:         const int axis = (code - ABS_HAT0X) % 2;
75:         int* state = js->linjs.hats[hat];
76: 
77:         // NOTE: Looking at several input drivers, it seems all hat events use
78:         //       -1 for left / up, 0 for centered and 1 for right / down
79:         if (value == 0)
80:             state[axis] = 0;
81:         else if (value < 0)
82:             state[axis] = 1;
83:         else if (value > 0)
84:             state[axis] = 2;
85: 
86:         _glfwInputJoystickHat(js, index, stateMap[state[0]][state[1]]);
87:     }
88:     else
89:     {
90:         const struct input_absinfo* info = &js->linjs.absInfo[code];
91:         float normalized = value;
92: 
93:         const int range = info->maximum - info->minimum;
94:         if (range)
95:         {
96:             // Normalize to 0.0 -> 1.0
97:             normalized = (normalized - info->minimum) / range;
98:             // Normalize to -1.0 -> 1.0
99:             normalized = normalized * 2.0f - 1.0f;
100:         }
101: 
102:         _glfwInputJoystickAxis(js, index, normalized);
103:     }
